-- Editorial CMS, private assets and exact-revision customer publication permission.
create table public.library_assets(id uuid primary key default gen_random_uuid(),bucket text not null default 'library-media' check(bucket='library-media'),storage_key text not null unique,mime text not null check(mime in ('video/mp4','image/jpeg','image/png','image/webp')),size bigint not null check(size>0 and size<=case when mime='video/mp4' then 20971520 else 5242880 end),checksum text not null default 'pending',release_state text not null default 'quarantine' check(release_state in ('quarantine','released','rejected')),uploader uuid not null references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.library_posts(id uuid primary key default gen_random_uuid(),payload jsonb not null,version integer not null default 1,content_revision integer not null default 1,state text not null default 'draft' check(state in ('draft','public')),published_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.library_previews(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.library_posts,session_id uuid not null references public.lookup_sessions on delete cascade,content_revision integer not null,expires_at timestamptz not null default now()+interval '15 minutes');
-- Session UUID is historical evidence, not a FK: technical session TTL must not delete consent or be blocked by append-only evidence.
create table public.library_consents(event_seq bigint generated always as identity primary key,post_id uuid not null references public.library_posts,session_id uuid not null,content_revision integer not null,granted boolean not null,notice_version text not null default 'library-v1',created_at timestamptz not null default now());
create trigger immutable_library_consent before update or delete on public.library_consents for each row execute function public.reject_event_mutation();
alter table public.library_assets enable row level security;alter table public.library_posts enable row level security;alter table public.library_previews enable row level security;alter table public.library_consents enable row level security;
revoke all on public.library_assets,public.library_posts,public.library_previews,public.library_consents from anon,authenticated;
grant all on public.library_assets,public.library_posts,public.library_previews,public.library_consents to service_role;
grant usage,select on sequence public.library_consents_event_seq_seq to service_role;
insert into storage.buckets(id,name,public,file_size_limit) values('library-media','library-media',false,20971520) on conflict(id) do nothing;

create function public.release_library_asset(p_actor uuid,p_asset uuid,p_key text,p_checksum text,p_size bigint) returns void language plpgsql security definer set search_path='' as $$declare a public.library_assets;begin
 perform public.require_admin(p_actor,true);select * into strict a from public.library_assets where id=p_asset for update;
 if a.release_state<>'quarantine' or a.checksum !~ '^[a-f0-9]{64}$' or p_checksum !~ '^[a-f0-9]{64}$' or p_size<1 or p_key not like a.id::text||'/%' then raise exception 'invalid release';end if;
 update public.library_assets set storage_key=p_key,checksum=p_checksum,size=p_size,release_state='released',updated_at=now() where id=p_asset;
 insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'library_asset_validated',p_asset,array['checksum','storage_key','release_state']);end$$;
create function public.immutable_library_asset() returns trigger language plpgsql set search_path='' as $$begin if old.release_state='released' and new is distinct from old then raise exception 'released asset immutable';end if;return new;end$$;
create trigger library_asset_immutable before update on public.library_assets for each row execute function public.immutable_library_asset();

create function public.save_library_post(p_actor uuid,p_id uuid,p_version integer,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.library_posts;begin
 perform public.require_admin(p_actor,true);
 if jsonb_typeof(p_payload) is distinct from 'object' or jsonb_typeof(p_payload->'title') is distinct from 'string' or jsonb_typeof(p_payload->'body') is distinct from 'string' or jsonb_typeof(p_payload->'category') is distinct from 'string' or jsonb_typeof(p_payload->'kind') is distinct from 'string' or jsonb_typeof(p_payload->'rights_confirmed') is distinct from 'boolean' or jsonb_typeof(p_payload->'video_id') is distinct from 'string' or jsonb_typeof(p_payload->'cover_id') is distinct from 'string' or length(trim(p_payload->>'title')) not between 1 and 160 or length(trim(p_payload->>'body')) not between 1 and 20000 or p_payload::text ~ '[<>]' or p_payload->>'kind' not in ('editorial','customer') or p_payload->>'category' not in ('Câu chuyện','Bản thân','Tình duyên','Công danh','Phong thủy') or not p_payload ?& array['title','body','kind','category','video_id','cover_id','order_id','rights_confirmed'] then raise exception 'invalid content';end if;
 if p_payload->>'kind'='customer' then perform 1 from public.orders where id=(p_payload->>'order_id')::uuid; if not found then raise exception 'order required';end if;elsif p_payload->>'order_id' is not null then raise exception 'editorial cannot reference order';end if;
 if p_id is null then insert into public.library_posts(payload) values(p_payload) returning * into r;
 else select * into strict r from public.library_posts where id=p_id and deleted_at is null for update;if r.version is distinct from p_version then raise exception using errcode='40001',message='post version conflict';end if;
 update public.library_posts set payload=p_payload,version=version+1,content_revision=content_revision+1,state='draft',updated_at=now() where id=p_id returning * into r;end if;
 insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'library_post_saved',r.id,array['payload','content_revision','state']);return to_jsonb(r);end$$;

create function public.library_asset_permission(p_asset uuid,p_order uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.attachments a join lateral(select * from public.consent_events c where c.asset_id=a.id and c.order_id=a.order_id and c.scope='website_public_gallery' order by c.event_seq desc limit 1)c on true where a.id=p_asset and a.order_id=p_order and a.classification='public_derivative' and a.release_state='released' and c.granted and c.age_band='18+' and c.asset_hash=a.checksum and c.asset_version=a.asset_version)$$;
create function public.library_post_allowed(p_id uuid) returns boolean language plpgsql stable security definer set search_path='' as $$declare r public.library_posts;o uuid;begin
 select * into strict r from public.library_posts where id=p_id;
 if coalesce((r.payload->>'rights_confirmed')::boolean,false) is not true then return false;end if;
 if r.payload->>'kind'='editorial' then return exists(select 1 from public.library_assets v,public.library_assets c where v.id=(r.payload->>'video_id')::uuid and c.id=(r.payload->>'cover_id')::uuid and v.mime='video/mp4' and c.mime in ('image/jpeg','image/png','image/webp') and v.release_state='released' and c.release_state='released');end if;
 o:=(r.payload->>'order_id')::uuid;
 return exists(select 1 from public.orders where id=o and inputs->>'age_band'='18+') and exists(select 1 from public.attachments v,public.attachments c where v.id=(r.payload->>'video_id')::uuid and c.id=(r.payload->>'cover_id')::uuid and v.mime='video/mp4' and c.mime in ('image/jpeg','image/png','image/webp')) and public.library_asset_permission((r.payload->>'video_id')::uuid,o) and public.library_asset_permission((r.payload->>'cover_id')::uuid,o) and coalesce((select granted and content_revision=r.content_revision from public.library_consents where post_id=r.id order by event_seq desc limit 1),false);
end$$;
create function public.transition_library_post(p_actor uuid,p_id uuid,p_version integer,p_action text) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.library_posts;begin
 perform public.require_admin(p_actor,true);select * into strict r from public.library_posts where id=p_id and deleted_at is null for update;
 if r.version is distinct from p_version then raise exception using errcode='40001',message='post version conflict';end if;
 if p_action not in ('publish','hide','delete') then raise exception 'action';end if;
 if r.payload->>'kind'='customer' then perform 1 from public.orders where id=(r.payload->>'order_id')::uuid for update;end if;
 if p_action='publish' and not public.library_post_allowed(r.id) then raise exception using errcode='23514',message='rights or validated media required';end if;
 update public.library_posts set state=case when p_action='publish' then 'public' else 'draft' end,version=version+1,published_at=case when p_action='publish' then coalesce(published_at,now()) else published_at end,deleted_at=case when p_action='delete' then now() else null end,updated_at=now() where id=p_id returning * into r;
 insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'library_post_'||p_action,r.id,array['state','version']);return to_jsonb(r);end$$;

create function public.preview_library_post(p_token text,p_csrf text,p_post uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.lookup_sessions;r public.library_posts;begin
 select * into strict s from public.lookup_sessions where token_digest=p_token and csrf_digest=p_csrf and expires_at>now() and revoked_at is null;
 select * into strict r from public.library_posts where id=p_post and deleted_at is null and payload->>'kind'='customer' and (payload->>'order_id')::uuid=s.order_id for update;
 insert into public.library_previews(post_id,session_id,content_revision) values(r.id,s.id,r.content_revision);
 return to_jsonb(r);end$$;
create function public.consent_library_post(p_token text,p_csrf text,p_post uuid,p_revision integer,p_granted boolean) returns void language plpgsql security definer set search_path='' as $$declare s public.lookup_sessions;r public.library_posts;begin
 select * into strict s from public.lookup_sessions where token_digest=p_token and csrf_digest=p_csrf and expires_at>now() and revoked_at is null;
 select * into strict r from public.library_posts where id=p_post and deleted_at is null and payload->>'kind'='customer' and (payload->>'order_id')::uuid=s.order_id for update;
 perform 1 from public.orders where id=s.order_id and inputs->>'age_band'='18+' for update;if not found then raise exception 'adult required';end if;
 if p_granted and (r.content_revision is distinct from p_revision or not exists(select 1 from public.library_previews where post_id=p_post and session_id=s.id and content_revision=r.content_revision and expires_at>now())) then raise exception 'exact preview required';end if;
 insert into public.library_consents(post_id,session_id,content_revision,granted) values(r.id,s.id,r.content_revision,p_granted);
 insert into public.audit_events(action,resource_id,changed_fields) values(case when p_granted then 'library_consent_granted' else 'library_consent_revoked' end,r.id,array['content_revision']);end$$;

create function public.public_library_posts() returns setof jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',r.id,'title',r.payload->>'title','body',r.payload->>'body','category',r.payload->>'category','published_at',r.published_at,'video',case when r.payload->>'kind'='editorial' then (select jsonb_build_object('bucket',bucket,'storage_key',storage_key) from public.library_assets where id=(r.payload->>'video_id')::uuid) else (select jsonb_build_object('bucket',bucket,'storage_key',storage_key) from public.attachments where id=(r.payload->>'video_id')::uuid) end,'cover',case when r.payload->>'kind'='editorial' then (select jsonb_build_object('bucket',bucket,'storage_key',storage_key) from public.library_assets where id=(r.payload->>'cover_id')::uuid) else (select jsonb_build_object('bucket',bucket,'storage_key',storage_key) from public.attachments where id=(r.payload->>'cover_id')::uuid) end) from public.library_posts r where state='public' and deleted_at is null and public.library_post_allowed(r.id) order by published_at desc,id limit 24$$;
do $$declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('release_library_asset','immutable_library_asset','save_library_post','library_asset_permission','library_post_allowed','transition_library_post','preview_library_post','consent_library_post','public_library_posts') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end$$;

create index library_posts_public_date on public.library_posts(published_at desc,id) where state='public' and deleted_at is null;
create index library_posts_order on public.library_posts((payload->>'order_id')) where deleted_at is null;
create index library_consents_latest on public.library_consents(post_id,event_seq desc);
create index library_previews_exact on public.library_previews(post_id,session_id,content_revision,expires_at);
